{
  "from": "正文/0065-画到不想给人看-ae-b-v1.md",
  "to": "正文/0065-画到不想给人看-ae-b-v2.md",
  "before_sha256": "3851a9bc48c4215e5b89af1d997963016b10ecacbeb8ac783c798f317b964cd2",
  "after_sha256": "1e5ef74f4e959a395ad38fcc29cf4d1555724240c68d1a680dfba2b02544ab2b",
  "han": 22198,
  "chars": 26935,
  "pages": 15,
  "changes": [
    {
      "before": "她把笔收掉，先用两张买纸时带的普通包装纸分别覆住新旧两张，再将它们同余下八张空白分层收进自己装纸的袋。",
      "after": "她把笔收掉，将两张画背面相对，画面都朝外，不把新旧两面压在一起。原先垫纸的旧硬纸折在外头护住，沾过橡皮屑的包装边避开画面，余下八张空白另留在袋内一侧。她慢慢将这几层送回自己装纸的袋，没有来回抽动。",
      "reason": "买纸只明示一张旧硬纸，删除凭空出现的两张包装纸并交代实际收纸动作。"
    },
    {
      "before": "他拿起书，先摸到昨天折痕旁那个旧磨白角，",
      "after": "他拿起书，先摸到昨天见过的那个旧磨白角，",
      "reason": "删除没有前文依据的借书折痕。"
    },
    {
      "before": "沈禾洗完最后一只碗，才回房看画。第一张的灰隔着包装纸透不出来，她先摊第二张，",
      "after": "沈禾洗完最后一只碗，才回房看画。她先将旧硬纸放平，把两张画分开，又从家里另找两张干净的旧包装纸，摸过没有油湿，才各自盖住。第一张那块灰没蹭到第二张上，她松了口气，先摊第二张，",
      "reason": "在家明确取得新隔纸，接续夜间隔纸/分层描写。"
    },
    {
      "before": "上午买来时十张都白，",
      "after": "下工买来时十张都白，",
      "reason": "与16点下工后购买时间一致。"
    },
    {
      "before": "她从口袋摸出买刨刀时找回的硬币，放回零钱处，想起姑娘那个还没画完便被抱走的招牌，",
      "after": "她从随身包取出新刨刀，旋开盖，将里面的木屑倒掉。刨刀边口还有一小截没落，她轻磕两下才出来，重新旋紧，另收在铅笔旁，免得明早拿包又找不见。她想起姑娘那个还没画完便被抱走的招牌，",
      "reason": "实际手机付5元，无找币；保留新物实际整理动作。"
    },
    {
      "before": "刚才从母亲那句给看看里等来的不安，",
      "after": "刚才等着母亲那句给看看时的不安，",
      "reason": "母亲当时未真提出看新画，区分期待与实际话语。"
    },
    {
      "before": "她今天买的并不是新笔，",
      "after": "她今天用的并不是新笔，",
      "reason": "女自有笔不是今日新买。"
    },
    {
      "before": "左手仍像喝水时那样松握，放在杯旁，杯子移得足够远。",
      "after": "左手仍像喝水时那样松握，放在桌面空处。",
      "reason": "杯在外间，与后文取杯扑空一致。"
    },
    {
      "before": "抽屉没动，没必要为核一条电话消息再打开。",
      "after": "抽屉没动，她仍靠着椅背，没有起身去取。",
      "reason": "去掉审核口吻。"
    }
  ]
}

