1	import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import assert from 'node:assert/strict';import{fileURLToPath}from'node:url';
2	const A=path.dirname(fileURLToPath(import.meta.url)),P=JSON.parse(fs.readFileSync(path.join(A,'project.json'))).project,read=r=>fs.readFileSync(path.join(P,r)),sha=b=>crypto.createHash('sha256').update(b).digest('hex');
3	const tr='.writer/drafts/ae-b-record64-original.json',t=JSON.parse(read(tr)),s=JSON.parse(read('.writer/state.json'));assert.equal(s.revision,362);assert.equal(t.expected_revision,362);for(const [r,h]of Object.entries(t.source_hashes))assert.equal(sha(read(r)),h,r);
4	t.draft='正文/0064-把这一边转过来-ae-b-v2.md';const text=read(t.draft).toString('utf8');
